BASE_DELAY = 1
CAP_DELAY = 16
FACTOR = 2


def retry_delay(attempt):
    """Return the delay in seconds before the given retry attempt.

    Attempt 0 uses the base delay; each subsequent attempt multiplies the
    delay by ``FACTOR``, capped at ``CAP_DELAY``. ``attempt`` must be a
    non-negative integer (``bool`` is rejected).
    """
    if isinstance(attempt, bool) or not isinstance(attempt, int):
        raise ValueError("attempt must be a non-negative integer")
    if attempt < 0:
        raise ValueError("attempt must be a non-negative integer")

    # Avoid constructing huge integers: once the exponent is large enough
    # the result is guaranteed to be capped.
    if attempt >= CAP_DELAY.bit_length():
        return CAP_DELAY
    return min(BASE_DELAY * (FACTOR ** attempt), CAP_DELAY)
"}]}

